                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.Tuco_Kids_shopify_fact_items_intermediate; CREATE TABLE public.Tuco_Kids_shopify_fact_items_intermediate AS SELECT o.shop_name, COALESCE(o.shop_name, \'WEBSITE\') AS marketplace, o.order_id, o.order_name, customer.id AS customer_id, o.name, o.email, o.phone, o.tags, CASE WHEN (LOWER(o.name::varchar) LIKE \'%market%\' OR LOWER(o.name::varchar) LIKE \'%inf\' OR LOWER(o.tags::varchar) LIKE \'%inf%\') THEN \'Influencer Order\' WHEN LOWER(o.source_name::varchar) LIKE \'%shopify_draft_order%\' THEN \'Shopify Draft Order\' WHEN LOWER(o.source_name::varchar) = \'2919509\' THEN \'Richpanel Draft Order\' WHEN LOWER(o.tags::varchar) LIKE \'%test order%\' THEN \'Test Order\' WHEN LOWER(o.tags::varchar) LIKE \'%return_prime%\' THEN \'Return Prime Order\' ELSE NULL END as order_type, o.line_item_id, o.sku, o.product_id, o.currency, o.cancelled_at, o.is_refund, o.utm_source_temp, o.utm_medium_temp, o.channel_temp, UPPER(o.shipping_address.city::varchar) AS shipping_city, UPPER(o.shipping_address.province::varchar) AS shipping_state, CASE WHEN cd.city IS NULL OR cd.city = \'\' THEN \'NA\' ELSE UPPER(cd.city::varchar) END AS city, CASE WHEN cd.province IS NULL OR cd.province = \'\' THEN \'NA\' ELSE UPPER(cd.province::varchar) END AS state, CASE WHEN p.title = \'\' THEN \'NA\' ELSE UPPER(p.title::varchar) END AS product_name, CASE WHEN p.product_type = \'\' THEN \'NA\' ELSE UPPER(p.product_type) END AS category, UPPER(COALESCE(CASE WHEN UPPER(COALESCE(o.shop_name, \'WEBSITE\')) = \'SHOPIFY POS\' AND o.is_refund = 1 THEN \'Cancelled\' END, o.order_status)) AS order_status, o.order_timestamp, o.line_item_sales, o.quantity, o.refund_quantity, o.refund_value, o.refund_date_final, o.refund_amount_without_lineitem, o.tax, o.tax_rate, o.discount, o.discount_codes, o.discount_before_tax, o.gross_sales_after_tax, o.gross_sales_before_tax, o.net_sales_before_tax, (COALESCE(o.shipping_price, 0) - COALESCE(o.total_shipping_discount, 0)) AS shipping_price, COALESCE(o.total_sales, 0) AS total_sales, o.moments_count, o.daystoconvert, o.shopifyql_firstvisit_utm_source, o.shopifyql_mapped_source, o.shopifyql_mapped_channel, o.shopifyql_last_moment_utm_source, o.shopifyql_last_visit_non_utm_source, o.shopifyql_firstvisit_utm_medium, o.shopifyql_last_moment_utm_medium, TRIM(o.final_utm_channel) as final_utm_channel, o.final_utm_campaign, o.final_utm_source, o.referrer_name, o.checkout_mapped_source, o.checkout_mapped_channel, o.awb, UPPER(o.courier) AS courier, UPPER(o.shipping_status) AS shipping_status, o.shipping_status_update_date, o.tracking_url, o.shipping_created_at, o.gateway, o.payment_mode, o.pincode, o.source_name, o.location_id FROM public.shopify_all_orders_items o LEFT JOIN public.shopify_all_products p ON CAST(o.product_id AS VARCHAR) = CAST(p.id AS VARCHAR) LEFT JOIN ( select * from ( SELECT customer_id, city, province, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY id DESC) AS rowid FROM public.shopify_all_customers_addresses ) where rowid = 1) cd ON o.customer.id::varchar = CAST(cd.customer_id AS VARCHAR); DROP TABLE IF EXISTS public.Tuco_Kids_sku_master; CREATE TABLE public.Tuco_Kids_sku_master ( ean VARCHAR(50), commonsku VARCHAR(100), set_of INT, gst_rate FLOAT, sub_category VARCHAR(100), category VARCHAR(100), gst_class VARCHAR(100), product_name VARCHAR(255), new_hsn_from_17_sept_25 VARCHAR(50), product_launch_date VARCHAR(50), product_image_url VARCHAR(500), brand VARCHAR(100), cogs FLOAT, tax_rule_name VARCHAR(100), product_type VARCHAR(100), mrp VARCHAR(50) ); DROP TABLE IF EXISTS public.shopify_fact_items_temp_category; CREATE TABLE public.shopify_fact_items_temp_category AS SELECT fi.*, COALESCE(p.commonsku, fi.sku) AS sku_code, UPPER(COALESCE(p.product_name, fi.product_name)) as product_name_final, COALESCE(UPPER(p.category), UPPER(fi.category)) AS product_category, UPPER(p.sub_category) as product_sub_category, p.commonsku, p.ean, p.gst_rate, p.new_hsn_from_17_sept_25 as hsn, p.product_image_url, p.cogs FROM public.Tuco_Kids_shopify_fact_items_intermediate fi LEFT JOIN ( SELECT * FROM ( SELECT ean, commonsku, category, sub_category, gst_rate, product_name, new_hsn_from_17_sept_25, product_launch_date, product_image_url, cogs, ROW_NUMBER() OVER (PARTITION BY commonsku ORDER BY LENGTH(COALESCE(commonsku, \'\')) DESC) rw FROM public.Tuco_Kids_sku_master ) WHERE rw = 1 ) p ON LOWER(REPLACE(fi.sku::varchar, \' \', \'\')) = LOWER(p.commonsku) ; DROP TABLE IF EXISTS public.Tuco_Kids_shopify_fact_items_intermediate; CREATE TABLE public.Tuco_Kids_shopify_fact_items_intermediate AS SELECT * FROM public.shopify_fact_items_temp_category; DROP TABLE IF EXISTS public.Tuco_Kids_shopify_final_customerid; CREATE TABLE public.Tuco_Kids_shopify_final_customerid AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT SUBSTRING(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), \'[^a-zA-Z0-9]+\', \'\'), -10) AS contact_num, phone FROM public.Tuco_Kids_shopify_fact_items_intermediate ) a ), int AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, SUBSTRING(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), -10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT REPLACE(phone, \' \', \'\') AS contact_num, email FROM public.Tuco_Kids_shopify_fact_items_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = SUBSTRING(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), -10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM int WHERE COALESCE(contact_num, email) IS NOT NULL; DROP TABLE IF EXISTS public.Tuco_Kids_shopify_fact_items; CREATE TABLE public.Tuco_Kids_shopify_fact_items AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS shopify_customer_id_final, MIN(CAST(m.order_timestamp AS DATE)) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS shopify_acquisition_date, MIN(CASE WHEN LOWER(m.order_status) NOT IN (\'cancelled\') THEN CAST(m.order_timestamp AS DATE) END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS shopify_first_complete_order_date, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM public.Tuco_Kids_shopify_fact_items_intermediate o LEFT JOIN ( SELECT contact_num AS phone, maple_monk_id FROM ( SELECT contact_num, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM public.tuco_kids_shopify_final_customerid ) WHERE magic = 1 ) c ON c.phone = SUBSTRING(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), -10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM public.Tuco_Kids_shopify_final_customerid WHERE contact_num IS NULL ) d ON d.email = m.email; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN shopify_new_customer_flag VARCHAR; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN shopify_new_customer_flag_month VARCHAR; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN shopify_acquisition_product VARCHAR; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN shopify_acquisition_channel VARCHAR; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN shopify_acquisition_source VARCHAR; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN shipping_tax FLOAT; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN ship_promotion_discount FLOAT; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN gift_wrap_price FLOAT; ALTER TABLE public.Tuco_Kids_shopify_fact_items ADD COLUMN gift_wrap_tax FLOAT; UPDATE public.Tuco_Kids_shopify_fact_items AS a SET shopify_new_customer_flag = b.flag FROM ( SELECT order_id, shopify_customer_id_final, order_timestamp::date AS order_date, CASE WHEN shopify_first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN order_timestamp::date = shopify_first_complete_order_date THEN \'New\' WHEN order_timestamp::date > shopify_first_complete_order_date THEN \'Repeat\' WHEN order_timestamp::date < shopify_first_complete_order_date THEN \'Yet to make completed order\' END AS flag FROM public.Tuco_Kids_shopify_fact_items ) AS b WHERE a.order_id = b.order_id AND a.shopify_customer_id_final = b.shopify_customer_id_final AND a.order_timestamp::date = b.order_date; UPDATE public.Tuco_Kids_shopify_fact_items SET shopify_new_customer_flag = CASE WHEN shopify_new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' WHEN shopify_new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) IN (\'cancelled\') END) THEN \'Yet to make completed order\' ELSE shopify_new_customer_flag END; UPDATE public.Tuco_Kids_shopify_fact_items AS a SET shopify_new_customer_flag_month = b.flag FROM ( SELECT order_id, shopify_customer_id_final, order_timestamp::date AS order_date, DATE_TRUNC(\'month\', order_timestamp::date) AS order_month, DATE_TRUNC(\'month\', shopify_first_complete_order_date::date) AS first_month, CASE WHEN shopify_first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(\'month\', order_timestamp::date) = DATE_TRUNC(\'month\', shopify_first_complete_order_date::date) THEN \'New\' WHEN DATE_TRUNC(\'month\', order_timestamp::date) > DATE_TRUNC(\'month\', shopify_first_complete_order_date::date) THEN \'Repeat\' WHEN DATE_TRUNC(\'month\', order_timestamp::date) < DATE_TRUNC(\'month\', shopify_first_complete_order_date::date) THEN \'Yet to make completed order\' END AS flag FROM public.Tuco_Kids_shopify_fact_items ) b WHERE a.order_id = b.order_id AND a.shopify_customer_id_final = b.shopify_customer_id_final; UPDATE public.Tuco_Kids_shopify_fact_items SET shopify_new_customer_flag_month = CASE WHEN shopify_new_customer_flag_month IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' ELSE shopify_new_customer_flag_month END; DROP TABLE IF EXISTS public.Tuco_Kids_temp_source_1; CREATE TABLE public.Tuco_Kids_temp_source_1 AS SELECT shopify_customer_id_final, channel, source FROM ( SELECT DISTINCT shopify_customer_id_final, CAST(order_timestamp AS DATE) AS order_date, final_utm_source AS source, final_utm_channel AS channel, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(order_timestamp AS DATE) END) OVER (PARTITION BY shopify_customer_id_final) AS firstorderdate, ROW_NUMBER() OVER (PARTITION BY shopify_customer_id_final ORDER BY 1 DESC) rw FROM public.Tuco_Kids_shopify_fact_items ) res WHERE order_date = firstorderdate AND rw = 1; UPDATE public.Tuco_Kids_shopify_fact_items AS a SET shopify_acquisition_channel = b.channel FROM public.Tuco_Kids_temp_source_1 b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; UPDATE public.Tuco_Kids_shopify_fact_items AS a SET shopify_acquisition_source = b.source FROM public.Tuco_Kids_temp_source_1 b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; DROP TABLE IF EXISTS public.Tuco_Kids_temp_product_1; CREATE TABLE public.Tuco_Kids_temp_product_1 AS SELECT DISTINCT shopify_customer_id_final, product_name_final, ROW_NUMBER() OVER (PARTITION BY shopify_customer_id_final ORDER BY total_sales DESC) AS rowid FROM ( SELECT DISTINCT shopify_customer_id_final, CAST(order_timestamp AS DATE) AS order_date, product_name_final, total_sales, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(order_timestamp AS DATE) END) OVER (PARTITION BY shopify_customer_id_final) AS firstorderdate FROM public.Tuco_Kids_shopify_fact_items ) res WHERE order_date = firstorderdate; UPDATE public.Tuco_Kids_shopify_fact_items AS a SET shopify_acquisition_product = b.product_name_final FROM ( SELECT * FROM public.Tuco_Kids_temp_product_1 WHERE rowid = 1 ) b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final;",
